-- Reverts 0011_a1_lesson_text.sql. Like the forward migration, it applies only
-- while A1 has never been published.

UPDATE lessons SET body_md = replace(body_md, 'The course has **four modules** of short lessons. Modules one to three each end with a practice quiz that helps you check your understanding; module four ends with a practical exercise and a course summary that prepare you for the final exam. Quizzes do not count toward your certificate, and you can retake them as often as you like.', 'The course has **four modules**. Each module contains short lessons and ends with a quiz that helps you check your understanding. Quizzes do not count toward your certificate, and you can retake them as often as you like.') WHERE id = 'les_a1_welcome' AND instr(body_md, 'The course has **four modules** of short lessons. Modules one to three each end with a practice quiz that helps you check your understanding; module four ends with a practical exercise and a course summary that prepare you for the final exam. Quizzes do not count toward your certificate, and you can retake them as often as you like.') > 0 AND NOT EXISTS (SELECT 1 FROM courses WHERE id = 'crs_a1' AND published_at IS NOT NULL);
UPDATE draft_lessons SET body_md = replace(body_md, 'The course has **four modules** of short lessons. Modules one to three each end with a practice quiz that helps you check your understanding; module four ends with a practical exercise and a course summary that prepare you for the final exam. Quizzes do not count toward your certificate, and you can retake them as often as you like.', 'The course has **four modules**. Each module contains short lessons and ends with a quiz that helps you check your understanding. Quizzes do not count toward your certificate, and you can retake them as often as you like.') WHERE id = 'les_a1_welcome' AND instr(body_md, 'The course has **four modules** of short lessons. Modules one to three each end with a practice quiz that helps you check your understanding; module four ends with a practical exercise and a course summary that prepare you for the final exam. Quizzes do not count toward your certificate, and you can retake them as often as you like.') > 0 AND NOT EXISTS (SELECT 1 FROM courses WHERE id = 'crs_a1' AND published_at IS NOT NULL);
UPDATE lessons SET body_md = replace(body_md, 'according to the UN Food and Agriculture Organization (FAO AQUASTAT), agriculture as a whole, mostly irrigation, accounts for about 70% of global freshwater withdrawals.', 'according to the UN Food and Agriculture Organization, irrigated agriculture accounts for roughly 70% of global freshwater withdrawals.') WHERE id = 'les_a1_why_now' AND instr(body_md, 'according to the UN Food and Agriculture Organization (FAO AQUASTAT), agriculture as a whole, mostly irrigation, accounts for about 70% of global freshwater withdrawals.') > 0 AND NOT EXISTS (SELECT 1 FROM courses WHERE id = 'crs_a1' AND published_at IS NOT NULL);
